/// Writes zema_core's search rules as SQL for the catalog backend, plus a
/// pgTAP parity test with zema_core's own answers, so the server searches
/// exactly like the app. Run `dart run tool/generate_search_sql.dart` after
/// changing `lib/src/search/search_tables.dart`; a test fails if the
/// committed files are stale.
library;

import 'package:zema_core/zema_core.dart';

/// Paths of the generated files, relative to the repository root.
const migrationPath =
    'backend/supabase/migrations/20261029020000_search_rules.sql';
const parityTestPath =
    'backend/supabase/tests/database/004_search_parity.test.sql';

const _header =
    '-- GENERATED by packages/zema_core/tool/generate_search_sql.dart from\n'
    '-- packages/zema_core/lib/src/search/search_tables.dart. Do not edit;\n'
    '-- change the tables and run the generator again.\n';

/// The migration with the rule data and the search functions.
String searchRulesSql() {
  final b = StringBuffer(_header)
    ..writeln()
    ..writeln(
      'create extension if not exists fuzzystrmatch with schema extensions;',
    )
    ..writeln();

  // Single-character folds (Ethiopic rows and syllables, Latin accents),
  // applied with translate() after lower().
  final from = StringBuffer();
  final to = StringBuffer();
  for (var rune = 0x1200; rune <= 0x135A; rune++) {
    final folded = foldCharacter(rune);
    if (folded != String.fromCharCode(rune)) {
      from.writeCharCode(rune);
      to.write(folded);
    }
  }
  for (final MapEntry(:key, :value) in latinAccentFolds.entries) {
    from.write(key);
    to.write(value);
  }

  // Each Ethiopic syllable's consonant, already through the Latin folds.
  final consonants = <String>[];
  for (var rune = 0x1200; rune <= 0x135A; rune++) {
    final consonant = ethiopicRowConsonants[ethiopicRow(rune)];
    if (consonant != null) {
      consonants.add('($rune, ${_literal(_foldLatin(consonant))})');
    }
  }

  var foldLatin = 'input';
  for (final (from, to) in latinSpellingFolds) {
    foldLatin = 'replace($foldLatin, ${_literal(from)}, ${_literal(to)})';
  }

  b
    ..writeln(
      '-- Ethiopic syllable → its consonant(s) in Latin, after the Latin folds.',
    )
    ..writeln('create table public.search_syllable_consonants (')
    ..writeln('  code_point integer primary key,')
    ..writeln('  latin text not null')
    ..writeln(');')
    ..writeln(
      'alter table public.search_syllable_consonants enable row level security;',
    )
    ..writeln(
      'insert into public.search_syllable_consonants (code_point, latin) values',
    )
    ..writeln('  ${consonants.join(',\n  ')};')
    ..writeln()
    ..writeln(
      '-- Latin spellings of the same sound, in order (latinSpellingFolds).',
    )
    ..writeln('create function public.zema_fold_latin(input text)')
    ..writeln('returns text language sql immutable parallel safe')
    ..writeln('as \$\$ select $foldLatin \$\$;')
    ..writeln()
    ..writeln('-- Lower-case, then fold characters (ethiopicRowFolds,')
    ..writeln('-- ethiopicSyllableFolds, latinAccentFolds).')
    ..writeln('create function public.zema_fold_text(input text)')
    ..writeln('returns text language sql immutable parallel safe')
    ..writeln('as \$\$')
    ..writeln('  select translate(lower(coalesce(input, \'\')),')
    ..writeln('    ${_literal(from.toString())},')
    ..writeln('    ${_literal(to.toString())})')
    ..writeln('\$\$;')
    ..writeln()
    ..writeln(
      '-- normalize.dart searchWords: fold, drop marks (\\p{M}), split on',
    )
    ..writeln(
      '-- anything but letters and digits (\\p{L}, \\p{N}), drop noise and years.',
    )
    ..writeln('create function public.zema_search_words(input text)')
    ..writeln('returns text[] language plpgsql immutable parallel safe')
    ..writeln('as \$\$')
    ..writeln('declare')
    ..writeln('  noise constant text[] := ${_textArray(searchNoisePhrases)};')
    ..writeln('  words text[];')
    ..writeln('  kept text[] := \'{}\';')
    ..writeln('  phrase text[];')
    ..writeln('  noise_phrase text;')
    ..writeln('  i integer := 1;')
    ..writeln('  n integer;')
    ..writeln('  matched boolean;')
    ..writeln('begin')
    ..writeln('  words := array(')
    ..writeln('    select w from regexp_split_to_table(')
    ..writeln(
      '      regexp_replace(public.zema_fold_text(input), ${_literal('[${_ranges(_isMark)}]')}, \'\', \'g\'),',
    )
    ..writeln('      ${_literal('[^${_ranges(_isLetterOrDigit)}]+')}')
    ..writeln('    ) as w')
    ..writeln('    where w <> \'\'')
    ..writeln('  );')
    ..writeln('  n := coalesce(array_length(words, 1), 0);')
    ..writeln('  while i <= n loop')
    ..writeln('    if words[i] ~ \'^(19|20)[0-9][0-9]\$\' then')
    ..writeln('      i := i + 1;')
    ..writeln('      continue;')
    ..writeln('    end if;')
    ..writeln('    matched := false;')
    ..writeln('    foreach noise_phrase in array noise loop')
    ..writeln('      phrase := string_to_array(noise_phrase, \' \');')
    ..writeln('      if i + array_length(phrase, 1) - 1 <= n')
    ..writeln(
      '         and words[i:i + array_length(phrase, 1) - 1] = phrase then',
    )
    ..writeln('        i := i + array_length(phrase, 1);')
    ..writeln('        matched := true;')
    ..writeln('        exit;')
    ..writeln('      end if;')
    ..writeln('    end loop;')
    ..writeln('    if not matched then')
    ..writeln('      kept := kept || words[i];')
    ..writeln('      i := i + 1;')
    ..writeln('    end if;')
    ..writeln('  end loop;')
    ..writeln('  return kept;')
    ..writeln('end')
    ..writeln('\$\$;')
    ..writeln()
    ..writeln(
      '-- transliteration.dart consonantSkeleton: Ethiopic → consonants, Latin',
    )
    ..writeln('-- runs folded, vowels dropped, repeats collapsed.')
    ..writeln('create function public.zema_skeleton(word text)')
    ..writeln('returns text language plpgsql stable parallel safe')
    ..writeln(
      '-- Reads the consonant table, which is not readable through the API.',
    )
    ..writeln('security definer')
    ..writeln('set search_path = \'\'')
    ..writeln('as \$\$')
    ..writeln('declare')
    ..writeln('  spelled text := \'\';')
    ..writeln('  latin text := \'\';')
    ..writeln('  skeleton text := \'\';')
    ..writeln('  previous text;')
    ..writeln('  ch text;')
    ..writeln('  consonant text;')
    ..writeln('begin')
    ..writeln('  for i in 1 .. coalesce(length(word), 0) loop')
    ..writeln('    ch := substr(word, i, 1);')
    ..writeln('    if ascii(ch) between ${0x1200} and ${0x135A} then')
    ..writeln('      spelled := spelled || public.zema_fold_latin(latin);')
    ..writeln('      latin := \'\';')
    ..writeln('      select c.latin into consonant')
    ..writeln(
      '        from public.search_syllable_consonants c where c.code_point = ascii(ch);',
    )
    ..writeln('      spelled := spelled || coalesce(consonant, ch);')
    ..writeln('    else')
    ..writeln('      latin := latin || ch;')
    ..writeln('    end if;')
    ..writeln('  end loop;')
    ..writeln('  spelled := spelled || public.zema_fold_latin(latin);')
    ..writeln('  for i in 1 .. length(spelled) loop')
    ..writeln('    ch := substr(spelled, i, 1);')
    ..writeln(
      '    if strpos(${_literal(latinVowels)}, ch) > 0 or ch = previous then',
    )
    ..writeln('      continue;')
    ..writeln('    end if;')
    ..writeln('    skeleton := skeleton || ch;')
    ..writeln('    previous := ch;')
    ..writeln('  end loop;')
    ..writeln('  return skeleton;')
    ..writeln('end')
    ..writeln('\$\$;')
    ..writeln()
    ..writeln('create function public.zema_skeletons(words text[])')
    ..writeln('returns text[] language sql stable parallel safe')
    ..writeln(
      'as \$\$ select coalesce(array(select public.zema_skeleton(w) from unnest(words) with ordinality as t(w, i) order by i), \'{}\') \$\$;',
    )
    ..writeln()
    ..writeln('-- transliteration.dart _wordScore.')
    ..writeln(
      'create function public.zema_word_score(q text, qs text, t text, ts text)',
    )
    ..writeln('returns double precision language sql immutable parallel safe')
    ..writeln('as \$\$')
    ..writeln('  select case')
    ..writeln('    when q = t or (qs <> \'\' and qs = ts) then 1.0')
    ..writeln(
      '    when starts_with(t, q) or (qs <> \'\' and starts_with(ts, qs)) then 0.9',
    )
    ..writeln('    when length(q) <= 2 then 0.0')
    ..writeln('    when strpos(t, q) > 0 then 0.8')
    ..writeln('    when length(qs) < 3 or length(ts) < 3 then 0.0')
    ..writeln('    else greatest(0.0, greatest(')
    ..writeln(
      '      1.0 - extensions.levenshtein(qs, ts)::double precision / greatest(length(qs), length(ts)),',
    )
    ..writeln('      case when length(ts) > length(qs)')
    ..writeln(
      '        then 0.9 * (1.0 - extensions.levenshtein(qs, left(ts, length(qs)))::double precision / length(qs))',
    )
    ..writeln('        else 0.0 end))')
    ..writeln('  end')
    ..writeln('\$\$;')
    ..writeln()
    ..writeln(
      '-- transliteration.dart matchScore (arrays of words and skeletons).',
    )
    ..writeln(
      'create function public.zema_match_score(qw text[], qs text[], tw text[], ts text[])',
    )
    ..writeln('returns double precision language sql immutable parallel safe')
    ..writeln('as \$\$')
    ..writeln(
      '  select case when coalesce(cardinality(qw), 0) = 0 then 1.0 else (',
    )
    ..writeln('    select sum(best order by i) / cardinality(qw) from (')
    ..writeln('      select i, coalesce((')
    ..writeln(
      '        select max(public.zema_word_score(qw[i], qs[i], tw[j], ts[j]))',
    )
    ..writeln('        from generate_subscripts(tw, 1) as j), 0.0) as best')
    ..writeln('      from generate_subscripts(qw, 1) as i')
    ..writeln('    ) as per_word')
    ..writeln('  ) end')
    ..writeln('\$\$;')
    ..writeln()
    ..writeln('-- matchThreshold.')
    ..writeln('create function public.zema_match_threshold()')
    ..writeln('returns double precision language sql immutable parallel safe')
    ..writeln('as \$\$ select $matchThreshold::double precision \$\$;');
  return b.toString();
}

String _foldLatin(String text) {
  var folded = text;
  for (final (from, to) in latinSpellingFolds) {
    folded = folded.replaceAll(from, to);
  }
  return folded;
}

final _markPattern = RegExp(r'^\p{M}$', unicode: true);
final _letterOrDigitPattern = RegExp(r'^[\p{L}\p{N}]$', unicode: true);
bool _isMark(int rune) => _markPattern.hasMatch(String.fromCharCode(rune));
bool _isLetterOrDigit(int rune) =>
    _letterOrDigitPattern.hasMatch(String.fromCharCode(rune));

/// [test]'s code points as a regex bracket body of \u/\U ranges.
String _ranges(bool Function(int) test) {
  final b = StringBuffer();
  int? start;
  void close(int end) {
    if (start == null) return;
    b.write(_escape(start!));
    if (end > start!) b.write('-${_escape(end)}');
    start = null;
  }

  for (var rune = 0; rune <= 0x10FFFF; rune++) {
    // Surrogates are not characters.
    final inside = !(rune >= 0xD800 && rune <= 0xDFFF) && test(rune);
    if (inside) {
      start ??= rune;
    } else {
      close(rune - 1);
    }
  }
  close(0x10FFFF);
  return b.toString();
}

String _escape(int rune) => rune <= 0xFFFF
    ? '\\u${rune.toRadixString(16).padLeft(4, '0')}'
    : '\\U${rune.toRadixString(16).padLeft(8, '0')}';

String _literal(String text) => "'${text.replaceAll("'", "''")}'";

String _textArray(List<String> items) =>
    'array[${items.map(_literal).join(', ')}]::text[]';

