/// The server's search as zema_core defines it: a song's score is the best
/// of its title entry (title, transliteration, artist) and its distinct
/// lines; at least [matchThreshold]; best first, then by ID. The matching
/// line is the best line when it beats the title.
List<(String, String?)> expectedSearch(String query) {
  final key = SearchKey(query);
  if (key.isEmpty) return const [];
  final results = <(String, double, String?)>[];
  for (final (id, title, tr, artist, lines) in paritySongs) {
    final titleScore = matchScore(
      key,
      SearchKey([title, ?tr, ?artist].join(' ')),
    );
    double? lineScore;
    String? bestLine;
    final seen = <String>{};
    for (final (_, _, text, lineTr) in lines) {
      if (!seen.add(text)) continue;
      final s = matchScore(key, SearchKey([text, ?lineTr].join(' ')));
      if (lineScore == null || s > lineScore) {
        lineScore = s;
        bestLine = text;
      }
    }
    final lineWins = lineScore != null && lineScore > titleScore;
    final score = lineWins ? lineScore : titleScore;
    if (score >= matchThreshold) {
      results.add((id, score, lineWins ? bestLine : null));
    }
  }
  results.sort((a, b) {
    final byScore = b.$2.compareTo(a.$2);
    return byScore != 0 ? byScore : a.$1.compareTo(b.$1);
  });
  return [for (final (id, _, line) in results) (id, line)];
}

/// The pgTAP parity test.
String parityTestSql() {
  final b = StringBuffer(_header)
    ..writeln('begin;')
    ..writeln('create extension if not exists pgtap with schema extensions;')
    ..writeln()
    ..writeln(
      '-- Start from an empty catalog (the seed songs come back on rollback).',
    )
    ..writeln('delete from public.songs;')
    ..writeln();
  final checks = <String>[];
  for (final text in parityTexts) {
    final words = searchWords(text);
    checks.add(
      'select is(public.zema_search_words(${_literal(text)}), ${_textArray(words)}, '
      '${_literal('words of $text')});',
    );
    checks.add(
      'select is(public.zema_skeletons(public.zema_search_words(${_literal(text)})), '
      '${_textArray([for (final w in words) consonantSkeleton(w)])}, '
      '${_literal('skeletons of $text')});',
    );
  }
  for (final (q, t) in parityScores) {
    final score = matchScore(SearchKey(q), SearchKey(t));
    checks.add(
      'select is(round(public.zema_match_score('
      'public.zema_search_words(${_literal(q)}), public.zema_skeletons(public.zema_search_words(${_literal(q)})), '
      'public.zema_search_words(${_literal(t)}), public.zema_skeletons(public.zema_search_words(${_literal(t)})))::numeric, 9), '
      '${score.toStringAsFixed(9)}::numeric, ${_literal('score of $q in $t')});',
    );
  }
  // Songs and searches.
  final inserts = StringBuffer();
  for (final (id, title, tr, artist, lines) in paritySongs) {
    inserts.writeln(
      'insert into public.songs (id, title, transliteration, artist, status) values '
      '(${_literal(id)}, ${_literal(title)}, ${tr == null ? 'null' : _literal(tr)}, '
      '${artist == null ? 'null' : _literal(artist)}, \'approved\');',
    );
    final sections = <String, String>{};
    for (final (section, kind, _, _) in lines) {
      sections.putIfAbsent(section, () => kind);
    }
    for (final (i, MapEntry(key: section, value: kind))
        in sections.entries.indexed) {
      inserts.writeln(
        'insert into public.sections (song_id, id, kind, position) values '
        '(${_literal(id)}, ${_literal(section)}, \'$kind\', $i);',
      );
    }
    final positions = <String, int>{};
    for (final (section, _, text, lineTr) in lines) {
      final position = positions[section] = (positions[section] ?? -1) + 1;
      inserts.writeln(
        'insert into public.lines (song_id, section_id, position, text, transliteration) values '
        '(${_literal(id)}, ${_literal(section)}, $position, ${_literal(text)}, '
        '${lineTr == null ? 'null' : _literal(lineTr)});',
      );
    }
  }
  inserts.writeln(
    "insert into public.songs (id, title, status) values ('hidden-kidist', 'Kidist hidden', 'draft');",
  );
  for (final query in paritySearches) {
    final expected = expectedSearch(query);
    final values = expected.isEmpty
        ? 'select null::text, null::text where false'
        : 'values ${expected.map((e) => '(${_literal(e.$1)}, ${e.$2 == null ? 'null::text' : _literal(e.$2!)})').join(', ')}';
    checks.add(
      'select results_eq('
      '${_literal('select song_id::text, line_text from public.search_songs(${_literal(query)})')}, '
      '${_literal(values)}, ${_literal('search for "$query"')});',
    );
  }
  b
    ..writeln('select plan(${checks.length});')
    ..writeln()
    ..write(inserts)
    ..writeln()
    ..writeln('set local role anon;')
    ..writeln()
    ..writeln(checks.join('\n'))
    ..writeln()
    ..writeln('select * from finish();')
    ..writeln('rollback;');
  return b.toString();
}
